h", "content": [{"type": "text", "text": "注意方向性"}]}]}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#eff6ff", "borderColor": "#3b82f6", "icon": "📊"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "刷题建议：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "包容关系是类比推理的高频考点。区分种属和组成是关键。"}]}]}]}$$ AS jsonb), NULL, '判断推理-包容关系的核心知识点和解题方法。', category_node.id, CAST('["判断推理", "包容关系"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_xc_analogy_extension_inclusive", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
